package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64.encodeBase64String
 */
public class Base64_encodeBase64String_TriageGen1Test {

    @Test
    public void testEncodeBase64String_WithStandardData() {
        // Standard input: "Man" -> "TWFu"
        byte[] input = "Man".getBytes();
        String expected = "TWFu";
        String actual = Base64.encodeBase64String(input);
        assertEquals("The Base64 encoding for 'Man' should be 'TWFu'", expected, actual);
    }

    @Test
    public void testEncodeBase64String_WithEmptyArray() {
        // Empty array should return an empty string
        byte[] input = new byte[0];
        String expected = "";
        String actual = Base64.encodeBase64String(input);
        assertEquals("Encoding an empty byte array should return an empty string", expected, actual);
    }

    @Test
    public void testEncodeBase64String_WithNull() {
        // Testing null input. 
        // Note: In most Apache Commons Codec versions, passing null to encodeBase64 
        // results in a NullPointerException.
        try {
            Base64.encodeBase64String(null);
            fail("Expected NullPointerException for null input");
        } catch (NullPointerException e) {
            // Expected behavior
        }
    }

    @Test
    public void testEncodeBase64String_WithSpecialCharacters() {
        // Testing characters that might trigger padding or specific Base64 logic
        // Input: "\u0000\u0001\u0002"
        byte[] input = {0, 1, 2};
        // Base64 for [0, 1, 2] is "AAECAw=="
        String expected = "AAECAw==";
        String actual = Base64.encodeBase64String(input);
        assertEquals("The Base64 encoding for [0, 1, 2] should be 'AAECAw=='", expected, actual);
    }

    @Test
    public void testEncodeBase64String_WithLargeData() {
        // Testing a larger buffer to ensure line/chunking logic (if applicable) handles it
        byte[] input = new byte[1024];
        for (int i = 0; i < input.length; i++) {
            input[i] = (byte) (i % 128);
        }
        String actual = Base64.encodeBase64String(input);

        assertNotNull("The resulting string should not be null", actual);
        assertFalse("The resulting string should not be empty", actual.isEmpty());

        // Verify round-trip consistency
        byte[] decoded = Base64.decodeBase64(actual);
        assertArrayEquals("Decoded bytes should match original input", input, decoded);
    }
}
